output:
3040	             "[camera] TIMEOUT: only %lu VSYNC edges in 5s "
3041	             "(expected %lu)\n",
3042	             (unsigned long)vsync_now, (unsigned long)vsync_target);
3043	      syslog(LOG_ERR,
3044	             "[camera] Check: MCLK on P27, sensor powered, "
3045	             "DVP pins P29-P39\n");
3046	      ret = -ETIMEDOUT;
3047	    }
3048	  else
3049	    {
3050	      syslog(LOG_INFO, "[camera] DVP sync OK - %lu VSYNC edges captured\n",
3051	             (unsigned long)vsync_now);
3052	      ret = 0;
3053	    }
3054	
3055	cleanup_irq:
3056	  /* Always detach IRQ in sync test - we don't keep it running */
3057	
3058	  dvp_irq_detach();
3059	
3060	cleanup_ctrl:
3061	  /* Always restore controller registers */
3062	
3063	  dvp_ctrl_deconfig();
3064	
3065	  return ret;
