3068	/****************************************************************************
3069	 * Name: bk7258_camera_grab
3070	 *
3071	 * Description:
3072	 *   Phase 1 Round 2 Step 4b: DMA single frame capture to PSRAM.
3073	 *
3074	 *   Configures the CIS controller, attaches interrupts, fills the
3075	 *   target buffer with 0x5A pattern, waits for one complete frame
3076	 *   (YUV_ARRIVED interrupt), then hexdumps the first 256 bytes.
3077	 *
3078	 *   Prerequisites: camera init + camera buf must have been run.
3079	 *
3080	 *   On exit: interrupts are detached, controller registers restored.
3081	 *
3082	 ****************************************************************************/
3083	
3084	int bk7258_camera_grab(void)
3085	{
3086	  int ret;
3087	  int timeout_ms;
3088	  uint32_t frame_start;
3089	  volatile uint8_t *buf;
3090	  int i;
3091	
3092	  /* Check DVP pins are configured */
3093	
3094	  if (!g_dvp_pins_configed)
3095	    {
3096	      syslog(LOG_ERR,
3097	             "[camera] DVP pins not configured - run 'camera init' first\n");
3098	      return -ENODEV;
3099	    }
3100	
3101	  /* Check frame buffers allocated */
3102	
3103	  if (!g_framebuf_allocated)
3104	    {
3105	      syslog(LOG_ERR,
3106	             "[camera] Frame buffers not allocated - run 'camera buf' first\n");
3107	      return -ENOMEM;
3108	    }
3109	
3110	  /* Fill target buffer with 0x5A pattern - allows detection of
3111	   * whether DMA actually wrote data.
3112	   */
3113	
3114	  buf = g_camera_buf[0];
3115	  syslog(LOG_INFO, "[camera] Filling buf[0] with 0x5A pattern (%d bytes)\n",
3116	         CAMERA_FRAME_SIZE);
3117	
3118	  for (i = 0; i < CAMERA_FRAME_SIZE; i++)
3119	    {
3120	      buf[i] = 0x5A;
3121	    }
3122	
3123	  /* Configure DVP controller - output to buf[0] */
3124	
3125	  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
3126	  if (ret < 0)
3127	    {
3128	      syslog(LOG_ERR, "[camera] DVP ctrl config failed: %d\n", ret);
3129	      goto cleanup_ctrl;
3130	    }
3131	
3132	  /* Attach interrupt handler */
3133	
3134	  ret = dvp_irq_attach();
3135	  if (ret < 0)
3136	    {
3137	      syslog(LOG_ERR, "[camera] DVP IRQ attach failed: %d\n", ret);
3138	      goto cleanup_irq;
3139	    }
3140	
3141	  /* Wait for one complete frame - YUV_ARRIVED interrupt.
3142	   * Timeout 5 seconds.
3143	   */
3144	
3145	  frame_start = g_dvp_frame_count;
3146	  timeout_ms  = 5000;
3147	
3148	  syslog(LOG_INFO, "[camera] Waiting for frame (timeout %d ms)...\n",
3149	         timeout_ms);
3150	
3151	  while (timeout_ms > 0)
3152	    {
3153	      if (g_dvp_frame_count > frame_start)
3154	        {
3155	          break;
3156	        }
3157	
3158	      up_udelay(1000);  /* 1 ms */
3159	      timeout_ms--;
3160	    }
3161	
3162	  if (g_dvp_frame_count <= frame_start)
3163	    {
3164	      syslog(LOG_ERR,
3165	             "[camera] TIMEOUT: no frame received in 5s "
3166	             "(VSYNC=%lu FRAME=%lu)\n",
3167	             (unsigned long)g_dvp_vsync_count,
3168	             (unsigned long)g_dvp_frame_count);
3169	      ret = -ETIMEDOUT;
3170	      goto cleanup_irq;
3171	    }
3172	
3173	  syslog(LOG_INFO, "[camera] Frame captured - VSYNC=%lu FRAME=%lu\n",
3174	         (unsigned long)g_dvp_vsync_count,
3175	         (unsigned long)g_dvp_frame_count);
3176	
3177	  /* Hexdump first 256 bytes of captured frame.
3178	   * Byte order: VYUY (Cr=b0 Y0=b1 Cb=b2 Y1=b3, verified with red/blue).
3179	   * In neutral scenes: even bytes (U/V) ≈ 0x80, odd bytes (Y) vary.
3180	   */
3181	
3182	  syslog(LOG_INFO, "[camera] First 256 bytes of captured frame (VYUY):\n");
3183	
3184	  for (i = 0; i < 256; i += 16)
3185	    {
3186	      syslog(LOG_INFO,
3187	             "  %04X: %02X %02X %02X %02X %02X %02X %02X %02X "
3188	             "%02X %02X %02X %02X %02X %02X %02X %02X\n",
3189	             i,
3190	             buf[i + 0],  buf[i + 1],  buf[i + 2],  buf[i + 3],
3191	             buf[i + 4],  buf[i + 5],  buf[i + 6],  buf[i + 7],
3192	             buf[i + 8],  buf[i + 9],  buf[i + 10], buf[i + 11],
3193	             buf[i + 12], buf[i + 13], buf[i + 14], buf[i + 15]);
3194	    }
3195	
3196	  /* Check if buffer still contains 0x5A pattern - if so, DMA didn't write */
3197	
3198	  {
3199	    bool all_5a = true;
3200	    for (i = 0; i < 256; i++)
3201	      {
3202	        if (buf[i] != 0x5A)
3203	          {
3204	            all_5a = false;
3205	            break;
3206	          }
3207	      }
3208	
3209	    if (all_5a)
3210	      {
3211	        syslog(LOG_ERR,
3212	               "[camera] WARNING: buf[0] still 0x5A - DMA may not have "
3213	               "written data\n");
3214	        ret = -EIO;
3215	      }
3216	    else
3217	      {
3218	        syslog(LOG_INFO,
3219	               "[camera] DMA write verified - buf[0] contains non-0x5A data\n");
3220	        ret = 0;
3221	      }
3222	  }
3223	
3224	cleanup_irq:
3225	  dvp_irq_detach();
3226	
3227	cleanup_ctrl:
3228	  dvp_ctrl_deconfig();
3229	
3230	  return ret;
3231	}
