3233	/****************************************************************************
3234	 * Name: bk7258_camera_stream
3235	 *
3236	 * Description:
3237	 *   Phase 1 Round 3 Step 5: continuous capture with ping-pong buffering.
3238	 *
3239	 ****************************************************************************/
3240	
3241	int bk7258_camera_stream(int n_frames)
3242	{
3243	  int ret;
3244	  uint32_t elapsed_ms;
3245	  int captured;
3246	  int timeout_ms;
3247	  int i;
3248	
3249	  if (n_frames <= 0) n_frames = 30;
3250	  else if (n_frames > STREAM_BUF_MAX) n_frames = STREAM_BUF_MAX;
3251	
3252	  if (!g_dvp_pins_configed)
3253	    {
3254	      syslog(LOG_ERR, "[camera] DVP pins not configured\n");
3255	      return -ENODEV;
3256	    }
3257	
3258	  if (!g_framebuf_allocated)
3259	    {
3260	      syslog(LOG_ERR, "[camera] Frame buffers not allocated\n");
3261	      return -ENOMEM;
3262	    }
3263	
3264	  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
3265	  if (ret < 0) goto cleanup_ctrl;
3266	
3267	  ret = dvp_irq_attach();
3268	  if (ret < 0) goto cleanup_irq;
3269	
3270	  g_dvp_vsync_count = 0;
3271	  g_dvp_frame_count = 0;
3272	  g_pingpong_count  = 0;
3273	  g_drop_count      = 0;
3274	  g_cur_buf         = 0;
3275	  g_ready_buf       = -1;
3276	  g_busy_buf        = -1;
3277	  g_stream_active   = true;
3278	
3279	  syslog(LOG_INFO,
3280	         "[camera] Stream start: capturing %d frames "
3281	         "(buf[0]=0x%08lX buf[1]=0x%08lX)\n",
3282	         n_frames,
3283	         (unsigned long)(uintptr_t)g_camera_buf[0],
3284	         (unsigned long)(uintptr_t)g_camera_buf[1]);
3285	
3286	  captured = 0;
3287	
3288	  while (captured < n_frames)
3289	    {
3290	      uint32_t frame_addr;
3291	
3292	      timeout_ms = 5000;
3293	      while (timeout_ms > 0)
3294	        {
3295	          frame_addr = dvp_frame_get();
3296	          if (frame_addr != 0) break;
3297	          up_udelay(1000);
3298	          timeout_ms--;
3299	        }
3300	
3301	      if (frame_addr == 0)
3302	        {
3303	          syslog(LOG_ERR, "[camera] TIMEOUT waiting for frame %d/%d\n",
3304	                 captured + 1, n_frames);
3305	          ret = -ETIMEDOUT;
3306	          break;
3307	        }
3308	
3309	      captured++;
3310	
3311	      {
3312	        const uint8_t *buf = (const uint8_t *)(uintptr_t)frame_addr;
3313	        uint32_t y_sum = 0;
3314	        int samples = 0;
3315	
3316	        for (i = 0; i < CAMERA_FRAME_SIZE; i += 16 * CAMERA_HRES)
3317	          {
3318	            int j;
3319	            for (j = 0; j < CAMERA_HRES; j += 16)
3320	              {
3321	                y_sum += buf[i + j];
3322	                samples++;
3323	              }
3324	          }
3325	
3326	        if (captured == 1 || captured == n_frames || (captured % 10) == 0)
3327	          {
3328	            syslog(LOG_INFO,
3329	                   "[camera] %d/%d  VSYNC=%lu  FRAME=%lu  "
3330	                   "Y_avg=%lu  drop=%lu\n",
3331	                   captured, n_frames,
3332	                   (unsigned long)g_dvp_vsync_count,
3333	                   (unsigned long)g_dvp_frame_count,
3334	                   (unsigned long)(samples > 0 ? y_sum / samples : 0),
3335	                   (unsigned long)g_drop_count);
3336	          }
3337	      }
3338	
3339	      dvp_frame_put();
3340	    }
3341	
3342	  g_stream_active = false;
3343	
3344	  elapsed_ms = g_dvp_frame_count > 0 ? (uint32_t)g_dvp_frame_count * 33 : 0;
3345	
3346	  syslog(LOG_INFO,
3347	         "[camera] Stream done: captured=%d  total=%lu  drop=%lu  vsync=%lu\n",
3348	         captured,
3349	         (unsigned long)g_pingpong_count,
3350	         (unsigned long)g_drop_count,
3351	         (unsigned long)g_dvp_vsync_count);
3352	
3353	  if (elapsed_ms > 0)
3354	    {
3355	      syslog(LOG_INFO, "[camera] Elapsed: ~%lu ms  Avg FPS: ~%lu\n",
3356	             (unsigned long)elapsed_ms,
3357	             (unsigned long)(captured * 1000 / (elapsed_ms > 0 ? elapsed_ms : 1)));
3358	    }
3359	
3360	  ret = captured > 0 ? 0 : -EIO;
3361	
3362	cleanup_irq:
3363	  dvp_irq_detach();
3364	cleanup_ctrl:
3365	  dvp_ctrl_deconfig();
3366	  return ret;
3367	}
