3369	/****************************************************************************
3370	 * VYUY -> RGB565 scaled conversion
3371	 *
3372	 * GC2145 (reg 0x84 = 0x02) produces VYUY byte order in PSRAM:
3373	 *   byte0=Cr(V), byte1=Y0, byte2=Cb(U), byte3=Y1
3374	 *
3375	 * Established 2026-08-21 by pointing the sensor at full-screen
3376	 * pure red and pure blue:
3377	 *   red  -> byte0 mean 230 (high Cr), byte2 mean 101 (low Cb)
3378	 *   blue -> byte0 mean 127,           byte2 mean 219 (high Cb)
3379	 * A face confirms: byte2 114 < 128 < byte0 144 (skin: Cb < Cr).
3380	 *
3381	 * The earlier "UYVY verified by memory dump" claim was invalid:
3382	 * that dump was on a grey scene where Cb~Cr~128, indistinguishable.
3383	 *
3384	 * VYUY 4-byte layout per 2 pixels:
3385	 *   [V   Y0  U   Y1]   i.e.   [Cr  Y0  Cb  Y1]
3386	 *    b0  b1  b2  b3
3387	 *
3388	 * Pixel sx, pair pointer p = row + (sx & ~1) * 2:
3389	 *   Y = p[1 + (sx&1)*2],  Cr = p[0],  Cb = p[2]
3390	 ****************************************************************************/
3391	
3392	static void uyvy_to_rgb565_scaled(const uint8_t *src,
3393	                                  uint8_t *dst,
3394	                                  int src_w, int src_h,
3395	                                  int dst_w, int dst_h)
3396	{
3397	  int sx, sy, dx, dy;
3398	  uint8_t *out = dst;
3399	  int scale_x = src_w / dst_w;
3400	  int scale_y = src_h / dst_h;
3401	
3402	  for (dy = 0; dy < dst_h; dy++)
3403	    {
3404	      sy = dy * scale_y;
3405	      const uint8_t *row = src + sy * src_w * 2;
3406	
3407	      for (dx = 0; dx < dst_w; dx++)
3408	        {
3409	          uint8_t y0;
3410	          int cb_i, cr_i, r, g, b;
3411	          uint16_t rgb;
3412	          int pos;
3413	
3414	          sx = dx * scale_x;
3415	
3416	          /* VYUY: pair pointer = start of 4-byte group */
3417	
3418	          const uint8_t *p = row + (sx & ~1) * 2;
3419	
3420	          y0   = p[1 + (sx & 1) * 2];     /* Y0=p[1], Y1=p[3] */
3421	          cr_i = (int)p[0] - 128;          /* Cr (V) = byte0 */
3422	          cb_i = (int)p[2] - 128;          /* Cb (U) = byte2 */
3423	
3424	          r = (int)y0 + cr_i + (cr_i * 51 / 128);
3425	          g = (int)y0 - (cb_i * 28 / 81) - (cr_i * 365 / 512);
3426	          b = (int)y0 + cb_i + (cb_i * 99 / 128);
3427	
3428	          if (r < 0) r = 0;
3429	          if (r > 255) r = 255;
3430	          if (g < 0) g = 0;
3431	          if (g > 255) g = 255;
3432	          if (b < 0) b = 0;
3433	          if (b > 255) b = 255;
3434	
3435	          /* Store as big-endian RGB565 (hi byte first) to match
3436	           * lcd_fill_rect byte order which drives this LCD correctly.
3437	           */
3438	
3439	          rgb = (uint16_t)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
3440	          pos = (dy * dst_w + dx) * 2;
3441	          out[pos]     = (uint8_t)(rgb >> 8);    /* hi = R[4:0] G[5:3] */
3442	          out[pos + 1] = (uint8_t)(rgb & 0xff);  /* lo = G[2:0] B[4:0] */
3443	        }
3444	    }
3445	}
