3447	/****************************************************************************
3448	 * Name: camera_bench_conversion
3449	 *
3450	 * Description:
3451	 *   A/B benchmark to separate PSRAM access bottleneck from XIP flash
3452	 *   instruction-fetch bottleneck in uyvy_to_rgb565_scaled().
3453	 *
3454	 *   Path A - "psram": convert directly from PSRAM source (scattered reads).
3455	 *   Path B - "sram" : memcpy a 160x160 VYUY crop to SRAM first, then
3456	 *            convert from there (sequential source reads).
3457	 *
3458	 *   Both paths output to the same destination buffer.  memcpy is timed
3459	 *   separately and reported independently.
3460	 *
3461	 *   Each path runs BENCH_ROUNDS iterations; elapsed time is accumulated
3462	 *   to overcome the 10 ms tick resolution.
3463	 *
3464	 ****************************************************************************/
3465	
3466	#define BENCH_ROUNDS     50
3467	#define BENCH_CROP_W     160
3468	#define BENCH_CROP_H     160
3469	#define BENCH_CROP_SIZE  (BENCH_CROP_W * BENCH_CROP_H * 2)
3470	#define BENCH_OUT_PIXELS (BENCH_CROP_W * BENCH_CROP_H)
3471	
3472	/* Real staging cost for Path A->SRAM: full 640x480 downscale touches
3473	 * 160 output rows x 640x2 = 1280 bytes per source row = 204800 bytes.
3474	 */
3475	
3476	#define BENCH_REAL_STAGING_BYTES (BENCH_CROP_H * CAMERA_HRES * 2)
3477	
3478	static void camera_bench_conversion(void)
3479	{
3480	  volatile uint8_t *psram;
3481	  const uint8_t *psram_src;
3482	  uint8_t *dst;
3483	  clock_t t0;
3484	  uint32_t elapsed_a;
3485	  uint32_t elapsed_c;
3486	  uint32_t elapsed_b;
3487	  uint32_t elapsed_memcpy;
3488	  uint32_t total_memcpy_bytes;
3489	  uint32_t throughput_kbps;
3490	  uint64_t ns_per_px;
3491	  int i;
3492	
3493	  /* SRAM staging buffer - 51200 bytes, holds one 160x160 VYUY crop */
3494	
3495	  static uint8_t sram_stage[BENCH_CROP_SIZE];
3496	
3497	  /* SRAM output buffer - keeps dst writes off PSRAM so ns/px reflects
3498	   * source-side cost only.  Adds 51200 B to .bss (total ~197 KB,
3499	   * well within the 344064-byte SRAM region).
3500	   */
3501	
3502	  static uint8_t sram_dst[BENCH_CROP_SIZE];
3503	
3504	  /* Ensure a frame buffer exists in PSRAM */
3505	
3506	  if (!g_framebuf_allocated)
3507	    {
3508	      printf("[bench] FAIL: no PSRAM framebuf"
3509	             " - run camera buf first\n");
3510	      return;
3511	    }
3512	
3513	  psram = g_camera_buf[0];
3514	
3515	  /* Fill with a deterministic VYUY test pattern so the benchmark is
3516	   * reproducible regardless of whether a real frame was captured.
3517	   * Luminance ramps horizontally, chroma is neutral (Cb=Cr=0x80).
3518	   */
3519	
3520	  printf("[bench] filling PSRAM with VYUY test pattern ...\n");
3521	
3522	  for (i = 0; i < CAMERA_FRAME_SIZE; i += 4)
3523	    {
3524	      uint8_t y0 = (uint8_t)((i >> 2) & 0xff);
3525	      uint8_t y1 = (uint8_t)(((i >> 2) + 1) & 0xff);
3526	
3527	      psram[i + 0] = 0x80;
3528	      psram[i + 1] = y0;
3529	      psram[i + 2] = 0x80;
3530	      psram[i + 3] = y1;
3531	    }
3532	
3533	  psram_src = (const uint8_t *)g_camera_buf[0];
3534	  dst = sram_dst;
3535	
3536	  /* Path A: PSRAM source, 640x480 -> 160x160 (scale 4x3).
3537	   * Memory: PSRAM (scattered reads, ~76800 accesses).
3538	   * Pattern: non-sequential (nearest-neighbour downscale).
3539	   */
3540	
3541	  printf("[bench] Path A:"
3542	         " PSRAM 640x480->160x160 (scattered) ...\n");
3543	
3544	  t0 = clock_systime_ticks();
3545	
3546	  for (i = 0; i < BENCH_ROUNDS; i++)
3547	    {
3548	      uyvy_to_rgb565_scaled(psram_src, dst,
3549	                            CAMERA_HRES, CAMERA_VRES,
3550	                            BENCH_CROP_W, BENCH_CROP_H);
3551	    }
3552	
3553	  elapsed_a = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
3554	
3555	  /* Path C: PSRAM source, 160x160 -> 160x160 (scale 1x1).
3556	   * Memory: PSRAM (sequential reads - first 51200 bytes).
3557	   * Pattern: sequential (1:1 copy, same instruction path as B).
3558	   *
3559	   * This isolates the access-pattern variable: A and C both read
3560	   * from PSRAM, but A scatters while C is sequential.
3561	   */
3562	
3563	  printf("[bench] Path C:"
3564	         " PSRAM 160x160->160x160 (sequential) ...\n");
3565	
3566	  t0 = clock_systime_ticks();
3567	
3568	  for (i = 0; i < BENCH_ROUNDS; i++)
3569	    {
3570	      uyvy_to_rgb565_scaled(psram_src, dst,
3571	                            BENCH_CROP_W, BENCH_CROP_H,
3572	                            BENCH_CROP_W, BENCH_CROP_H);
3573	    }
3574	
3575	  elapsed_c = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
3576	
3577	  /* memcpy: PSRAM -> SRAM, row-by-row 160x160 crop.
3578	   * 160 rows x 320 bytes/row = 51200 bytes per iteration.
3579	   * Measured to derive throughput; real staging cost extrapolated.
3580	   */
3581	
3582	  printf("[bench] memcpy"
3583	         " PSRAM->SRAM (row-by-row crop) ...\n");
3584	
3585	  t0 = clock_systime_ticks();
3586	
3587	  for (i = 0; i < BENCH_ROUNDS; i++)
3588	    {
3589	      int row;
3590	      int src_stride = CAMERA_HRES * 2;
3591	      int crop_stride = BENCH_CROP_W * 2;
3592	
3593	      for (row = 0; row < BENCH_CROP_H; row++)
3594	        {
3595	          memcpy(sram_stage + row * crop_stride,
3596	                 psram_src + row * src_stride,
3597	                 crop_stride);
3598	        }
3599	    }
3600	
3601	  elapsed_memcpy = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
3602	
3603	  /* Path B: SRAM source, 160x160 -> 160x160 (scale 1x1).
3604	   * Memory: SRAM (sequential reads).
3605	   * Pattern: sequential (identical to Path C).
3606	   *
3607	   * C vs B isolates the memory-type variable: same sequential
3608	   * pattern, but C reads PSRAM while B reads SRAM.
3609	   */
3610	
3611	  printf("[bench] Path B:"
3612	         " SRAM 160x160->160x160 (sequential) ...\n");
3613	
3614	  t0 = clock_systime_ticks();
3615	
3616	  for (i = 0; i < BENCH_ROUNDS; i++)
3617	    {
